/* ---------------- SelectCameraCar (src/pilot/SelectCameraCar.c) ---------------- */
int SelectCameraCar(int i)
{
    int j = i + 1;
    int n;
    int dx, dy;

    if (i >= 25)
        return 0;
    for (n = 0; n < 24; n++) {
        if (D_00098950[j - 1].f1 == 4) {
            dx = car_data[0].pos.vx - car_data[j].pos.vx;
            dy = car_data[0].pos.vz - car_data[j].pos.vz;
            dx = abs(dx);
            dy = abs(dy);
            if (dx < 8000 && dy < 8000)
                return j;
        }
        if (j >= 25)
            return 0;
        j++;
    }
    return 0;
}

